      {"id":15330382,"title":"Clinical Pharmacogenetics Implementation Consortium (CPIC) Guideline for Thiopurine Dosing Based on TPMT and NUDT15 Genotypes: 2025 Update.","_sameAs":"https://www.ncbi.nlm.nih.gov/pubmed/41618934","crossReferences":[{"id":1454649660,"resource":"PubMed","resourceId":"41618934","_url":"https://www.ncbi.nlm.nih.gov/pubmed/41618934"},{"id":1454649661,"resource":"DOI","resourceId":"10.1002/cpt.70209","_url":"http://dx.doi.org/10.1002%2Fcpt.70209"}],"objCls":"Literature","pubDate":"2026-01-01T00:00:00-08:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"},
