      {"id":15184982,"title":"Dutch Pharmacogenetics Working Group Guidelines September 2025","_sameAs":"https://api.pharmgkb.org/v1/preview/download/file/attachment/pharmacogenetic_recommendation_text_20240101_downloaded_090825.pdf","crossReferences":[{"id":1454247640,"resource":"URL","resourceId":"https://api.pharmgkb.org/v1/preview/download/file/attachment/pharmacogenetic_recommendation_text_20240101_downloaded_090825.pdf","_url":"https://api.pharmgkb.org/v1/preview/download/file/attachment/pharmacogenetic_recommendation_text_20240101_downloaded_090825.pdf"}],"objCls":"Literature","terms":[{"id":1452267780,"resource":"ClinPGx Tags","term":"Has PGx","termId":"pgkbTags:1452267780"}],"type":"Literature"}
