    "pediatricMarkdown" : {
      "id" : 1451818342,
      "html" : "<p>Excerpt from the DPWG guideline recommendations:</p>\\n<blockquote class=\\"blockquote\\">\\n<p>CYP2D6 UM [...] Choose an alternative or titrate the dose according to the maximum dose for the active metabolite (paliperidone) (oral 12 mg/day for adults and children from 15 years of age weighing at least 51 kg and 6 mg/day for children from 15 years of age weighing less than 51 kg; intramuscular 75 mg per 2 weeks).</p>\\n</blockquote>\\n",
      "version" : 0
    },
    "recommendation" : true,
    "relatedAlleles" : [],
