      {"id":15127862,"title":"Clinical Pharmacogenetics Implementation Consortium Guideline for CYP2C19 Genotype and Clopidogrel Therapy: 2022 Update.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9287492","crossReferences":[{"id":1451837619,"resource":"PubMed Central","resourceId":"PMC9287492","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9287492"},{"id":1451651460,"resource":"PubMed","resourceId":"35034351","_url":"https://www.ncbi.nlm.nih.gov/pubmed/35034351"},{"id":1451651461,"resource":"DOI","resourceId":"10.1002/cpt.2526","_url":"http://dx.doi.org/10.1002%2Fcpt.2526"}],"objCls":"Literature","pubDate":"2022-11-01T00:00:00-07:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"},
      {"id":15058235,"title":"Clinical Pharmacogenetics Implementation Consortium guidelines for CYP2C19 genotype and clopidogrel therapy: 2013 update.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3748366","crossReferences":[{"id":1449276503,"resource":"PubMed Central","resourceId":"PMC3748366","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3748366"},{"id":1449276502,"resource":"PubMed","resourceId":"23698643","_url":"https://www.ncbi.nlm.nih.gov/pubmed/23698643"},{"id":1449276504,"resource":"DOI","resourceId":"10.1038/clpt.2013.105","_url":"http://dx.doi.org/10.1038%2Fclpt.2013.105"}],"objCls":"Literature","pubDate":"2013-09-01T00:00:00-07:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"},
      {"id":8231172,"title":"Clinical Pharmacogenetics Implementation Consortium guidelines for cytochrome P450-2C19 (CYP2C19) genotype and clopidogrel therapy.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3234301","crossReferences":[{"id":1449250640,"resource":"PubMed Central","resourceId":"PMC3234301","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3234301"},{"id":827692890,"resource":"PubMed","resourceId":"21716271","_url":"https://www.ncbi.nlm.nih.gov/pubmed/21716271"},{"id":1449250641,"resource":"DOI","resourceId":"10.1038/clpt.2011.132","_url":"http://dx.doi.org/10.1038%2Fclpt.2011.132"}],"objCls":"Literature","pubDate":"2011-08-01T00:00:00-07:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"}
