    "literature" : [
      {"id":15098503,"title":"Clinical Pharmacogenetics Implementation Consortium (CPIC) Guideline for Pharmacogenetics-Guided Warfarin Dosing: 2017 Update.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5546947","crossReferences":[{"id":1449293783,"resource":"PubMed Central","resourceId":"PMC5546947","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5546947"},{"id":1449293782,"resource":"PubMed","resourceId":"28198005","_url":"https://www.ncbi.nlm.nih.gov/pubmed/28198005"},{"id":1449293784,"resource":"DOI","resourceId":"10.1002/cpt.668","_url":"http://dx.doi.org/10.1002%2Fcpt.668"}],"objCls":"Literature","pubDate":"2017-09-01T00:00:00-07:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"},
      {"id":8560040,"title":"Clinical Pharmacogenetics Implementation Consortium Guidelines for CYP2C9 and VKORC1 genotypes and warfarin dosing.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3187550","crossReferences":[{"id":1449251343,"resource":"PubMed Central","resourceId":"PMC3187550","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3187550"},{"id":827707800,"resource":"PubMed","resourceId":"21900891","_url":"https://www.ncbi.nlm.nih.gov/pubmed/21900891"},{"id":1449251344,"resource":"DOI","resourceId":"10.1038/clpt.2011.185","_url":"http://dx.doi.org/10.1038%2Fclpt.2011.185"}],"objCls":"Literature","pubDate":"2011-10-01T00:00:00-07:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"}
    ],
    "otherPrescribingGuidance" : false,
    "pediatric" : true,
    "pediatricMarkdown" : {
      "id" : 1451266800,
      "html" : "<p>Excerpts from the 2017 warfarin CPIC guideline update:</p>\\n<ul>\\n<li>&quot;<em><strong>Therapeutic Recommendations: Pediatric</strong></em><br />\\nIn children of European ancestry and if CYP2C9*2 and *3 and VKORC1-1639 genotype are available, calculate warfarin dosing based on a validated published pediatric pharmacogenetic algorithm (<a href=\\"#figure-3-dosing-recommendations-for-warfarin-dosing-based-on-genotype-for-pediatric-patients\\">Figure 3</a>) [Articles:<a href=\\"/pmid/22010099\\">22010099</a>, <a href=\\"/pmid/23307232\\">23307232</a>].  A dosing tool that can be used in children of European ancestry is available at http://www.warfarindoserevision.com [Article:<a href=\\"/pmid/24330000\\">24330000</a>].&quot;</li>\\n</ul>\\n",
      "version" : 0
    },
    "recommendation" : true,
    "relatedAlleles" : [
      {
