    "relatedGenes" : [
      {
        "objCls" : "Gene",
        "id" : "PA126",
        "symbol" : "CYP2C9",
        "name" : "cytochrome P450 family 2 subfamily C member 9",
        "version" : 7877
      },
      {
        "objCls" : "Gene",
        "id" : "PA27121",
