    "otherPrescribingGuidance" : true,
    "pediatric" : false,
    "recommendation" : true,
    "relatedAlleles" : [],
    "relatedChemicals" : [
      {
        "objCls" : "Chemical",
        "id" : "PA450379",
        "name" : "mercaptopurine",
