  "citations" : [
    {
      "id" : 15312280,
      "title" : "Dutch Pharmacogenetics Working Group (DPWG) guideline for the gene-drug interaction between TPMT/NUDT15 and thiopurines.",
      "_sameAs" : "https://www.ncbi.nlm.nih.gov/pubmed/41318725",
      "authors" : [
        "Coenen Marieke J H",
        "Nijenhuis Marga",
