      {"id":15104402,"title":"Dutch Pharmacogenetics Working Group (DPWG) guideline for the gene-drug interaction of DPYD and fluoropyrimidines.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC7080718","crossReferences":[{"id":1452680152,"resource":"PubMed Central","resourceId":"PMC7080718","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC7080718"},{"id":1450964680,"resource":"PubMed","resourceId":"31745289","_url":"https://www.ncbi.nlm.nih.gov/pubmed/31745289"},{"id":1450964681,"resource":"DOI","resourceId":"10.1038/s41431-019-0540-0","_url":"http://dx.doi.org/10.1038%2Fs41431-019-0540-0"}],"objCls":"Literature","pubDate":"2020-04-01T00:00:00-07:00","terms":[{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"},
      {"id":7283333,"title":"Pharmacogenetics: from bench to byte--an update of guidelines.","_sameAs":"https://www.ncbi.nlm.nih.gov/pubmed/21412232","crossReferences":[{"id":769250885,"resource":"PubMed","resourceId":"21412232","_url":"https://www.ncbi.nlm.nih.gov/pubmed/21412232"},{"id":1449247827,"resource":"DOI","resourceId":"10.1038/clpt.2011.34","_url":"http://dx.doi.org/10.1038%2Fclpt.2011.34"}],"objCls":"Literature","pubDate":"2011-05-01T00:00:00-07:00","terms":[],"type":"Literature"},
      {"id":15103288,"title":"Dutch Pharmacogenetics Working Group Guidelines August 2019","_sameAs":"https://api.pharmgkb.org/v1/preview/download/file/attachment/DPWG_August_2019.pdf","crossReferences":[{"id":1450815695,"resource":"URL","resourceId":"https://api.pharmgkb.org/v1/preview/download/file/attachment/DPWG_August_2019.pdf","_url":"https://api.pharmgkb.org/v1/preview/download/file/attachment/DPWG_August_2019.pdf"}],"objCls":"Literature","terms":[],"type":"Literature"},
