      {"id":15070904,"title":"Clinical Pharmacogenetics Implementation Consortium Guidelines for HLA-B Genotype and Abacavir Dosing: 2014 update.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3994233","crossReferences":[{"id":1449279728,"resource":"PubMed Central","resourceId":"PMC3994233","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3994233"},{"id":1449279727,"resource":"PubMed","resourceId":"24561393","_url":"https://www.ncbi.nlm.nih.gov/pubmed/24561393"},{"id":1449279729,"resource":"DOI","resourceId":"10.1038/clpt.2014.38","_url":"http://dx.doi.org/10.1038%2Fclpt.2014.38"}],"objCls":"Literature","pubDate":"2014-05-01T00:00:00-07:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"},
      {"id":14962778,"title":"Clinical pharmacogenetics implementation consortium guidelines for HLA-B genotype and abacavir dosing.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3374459","crossReferences":[{"id":1449267214,"resource":"PubMed Central","resourceId":"PMC3374459","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3374459"},{"id":827848488,"resource":"PubMed","resourceId":"22378157","_url":"https://www.ncbi.nlm.nih.gov/pubmed/22378157"},{"id":1449267215,"resource":"DOI","resourceId":"10.1038/clpt.2011.355","_url":"http://dx.doi.org/10.1038%2Fclpt.2011.355"}],"objCls":"Literature","pubDate":"2012-04-01T00:00:00-07:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"}
