      {"id":15090607,"title":"Clinical Pharmacogenetics Implementation Consortium (CPIC) guidelines for human leukocyte antigen B (HLA-B) genotype and allopurinol dosing: 2015 update.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC4675696","crossReferences":[{"id":1449286509,"resource":"PubMed Central","resourceId":"PMC4675696","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC4675696"},{"id":1449286508,"resource":"PubMed","resourceId":"26094938","_url":"https://www.ncbi.nlm.nih.gov/pubmed/26094938"},{"id":1449286510,"resource":"DOI","resourceId":"10.1002/cpt.161","_url":"http://dx.doi.org/10.1002%2Fcpt.161"}],"objCls":"Literature","pubDate":"2016-01-01T00:00:00-08:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"},
      {"id":15033427,"title":"Clinical Pharmacogenetics Implementation Consortium guidelines for human leukocyte antigen-B genotype and allopurinol dosing.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3564416","crossReferences":[{"id":1449274192,"resource":"PubMed Central","resourceId":"PMC3564416","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3564416"},{"id":1449274191,"resource":"PubMed","resourceId":"23232549","_url":"https://www.ncbi.nlm.nih.gov/pubmed/23232549"},{"id":1449274193,"resource":"DOI","resourceId":"10.1038/clpt.2012.209","_url":"http://dx.doi.org/10.1038%2Fclpt.2012.209"}],"objCls":"Literature","pubDate":"2013-02-01T00:00:00-08:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"}
