      {"id":15100356,"title":"Clinical Pharmacogenetics Implementation Consortium Guideline for HLA Genotype and Use of Carbamazepine and Oxcarbazepine: 2017 Update.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5847474","crossReferences":[{"id":1449292006,"resource":"PubMed Central","resourceId":"PMC5847474","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5847474"},{"id":1449292005,"resource":"PubMed","resourceId":"29392710","_url":"https://www.ncbi.nlm.nih.gov/pubmed/29392710"},{"id":1449292007,"resource":"DOI","resourceId":"10.1002/cpt.1004","_url":"http://dx.doi.org/10.1002%2Fcpt.1004"}],"objCls":"Literature","pubDate":"2018-04-01T00:00:00-07:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"},
      {"id":15058356,"title":"Clinical Pharmacogenetics Implementation Consortium guidelines for HLA-B genotype and carbamazepine dosing.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3748365","crossReferences":[{"id":1449276532,"resource":"PubMed Central","resourceId":"PMC3748365","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3748365"},{"id":1449276531,"resource":"PubMed","resourceId":"23695185","_url":"https://www.ncbi.nlm.nih.gov/pubmed/23695185"},{"id":1449276533,"resource":"DOI","resourceId":"10.1038/clpt.2013.103","_url":"http://dx.doi.org/10.1038%2Fclpt.2013.103"}],"objCls":"Literature","pubDate":"2013-09-01T00:00:00-07:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"}
