    "literature" : [
      {"id":15071835,"title":"Recommendations for HLA-B*15:02 and HLA-A*31:01 genetic testing to reduce the risk of carbamazepine-induced hypersensitivity reactions.","_sameAs":"https://www.ncbi.nlm.nih.gov/pubmed/24597466","crossReferences":[{"id":1449279963,"resource":"PubMed","resourceId":"24597466","_url":"https://www.ncbi.nlm.nih.gov/pubmed/24597466"},{"id":1449279964,"resource":"DOI","resourceId":"10.1111/epi.12564","_url":"http://dx.doi.org/10.1111%2Fepi.12564"}],"objCls":"Literature","pubDate":"2014-04-01T00:00:00-07:00","terms":[],"type":"Literature"}
    ],
    "otherPrescribingGuidance" : false,
    "pediatric" : false,
    "recommendation" : true,
    "relatedAlleles" : [
      {
        "objCls" : "Haplotype",
