      ],
      "day" : -1,
      "hasKeyword" : true,
      "journal" : "Journal of population therapeutics and clinical pharmacology = Journal de la therapeutique des populations et de la pharmacologie clinique",
      "meshTerms" : [
        "Analgesics, Opioid",
        "Codeine",
        "Cytochrome P-450 CYP2D6",
