    "name" : "Annotation of CPNDS Guideline for codeine and CYP2D6",
    "alternateDrugAvailable" : true,
    "cancerGenome" : false,
    "crossReferences" : [],
    "dosingInformation" : false,
    "hasTestingInfo" : true,
    "history" : [
      {
        "id" : 1184511456,
