    "alternateDrugAvailable" : true,
    "cancerGenome" : false,
    "crossReferences" : [],
    "descriptiveVideoId" : "U1PKEF6M9oM",
    "dosingInformation" : true,
    "hasTestingInfo" : false,
    "history" : [
      {
        "id" : 1448530671,
        "date" : "2016-12-02T00:00:00-08:00",
        "type" : "Create",
        "version" : 0
      },
      {
