    "literature" : [
      {"id":15099517,"title":"Clinical Practice Recommendations for the Management and Prevention of Cisplatin-Induced Hearing Loss Using Pharmacogenetic Markers.","_sameAs":"https://www.ncbi.nlm.nih.gov/pubmed/26960170","crossReferences":[{"id":1449284747,"resource":"PubMed","resourceId":"26960170","_url":"https://www.ncbi.nlm.nih.gov/pubmed/26960170"},{"id":1449284748,"resource":"DOI","resourceId":"10.1097/FTD.0000000000000298","_url":"http://dx.doi.org/10.1097%2FFTD.0000000000000298"}],"objCls":"Literature","pubDate":"2016-08-01T00:00:00-07:00","terms":[],"type":"Literature"}
    ],
    "otherPrescribingGuidance" : true,
    "pediatric" : true,
    "pediatricMarkdown" : {
      "id" : 1451822420,
      "html" : "<p>Excerpt from the CPNDS guideline:</p>\\n<blockquote class=\\"blockquote\\">\\n<p>We recommend pharmacogenetic testing for the associated functional TPMT variants (*3A, *3B, *3C) and the known, relatively common, and functionally inactive TPMT *2 variant in pediatric patients to receive cisplatin <em><strong>(level A â€“ strong recommendation)</strong></em></p>\\n</blockquote>\\n",
      "version" : 0
    },
    "recommendation" : true,
    "relatedAlleles" : [
