    "literature" : [
      {"id":15333442,"title":"Dutch Pharmacogenetics Working Group Guidelines April 2026","_sameAs":"https://api.clinpgx.org/v1/preview/download/file/attachment/pharmacogenetic_recommendation_text_20250501_downloaded042726.pdf","crossReferences":[{"id":1454748320,"resource":"URL","resourceId":"https://api.clinpgx.org/v1/preview/download/file/attachment/pharmacogenetic_recommendation_text_20250501_downloaded042726.pdf","_url":"https://api.clinpgx.org/v1/preview/download/file/attachment/pharmacogenetic_recommendation_text_20250501_downloaded042726.pdf"}],"objCls":"Literature","terms":[{"id":1452267780,"resource":"ClinPGx Tags","term":"Has PGx","termId":"pgkbTags:1452267780"}],"type":"Literature"},
