INSERT INTO guideline_raw (pharmgkb_id, json_data) VALUES ('PA166182821', '{
  "citations" : [],
  "guideline" : {
    "objCls" : "Guideline Annotation",
    "id" : "PA166182821",
    "name" : "Annotation of DPWG Guideline for sertraline and CYP2D6",
    "alternateDrugAvailable" : false,
    "cancerGenome" : false,
    "crossReferences" : [],
    "dosingInformation" : false,
    "hasTestingInfo" : false,
    "history" : [
