    "literature" : [
      {"id":15109243,"title":"Pharmacogenetics of immunosuppressants: State of the art and clinical implementation - recommendations from the French National Network of Pharmacogenetics (RNPGx).","_sameAs":"https://www.ncbi.nlm.nih.gov/pubmed/28318610","crossReferences":[{"id":1451127902,"resource":"PubMed","resourceId":"28318610","_url":"https://www.ncbi.nlm.nih.gov/pubmed/28318610"},{"id":1451127903,"resource":"DOI","resourceId":"10.1016/j.therap.2016.09.016","_url":"http://dx.doi.org/10.1016%2Fj.therap.2016.09.016"}],"objCls":"Literature","pubDate":"2017-04-01T00:00:00-07:00","terms":[],"type":"Literature"}
