    "literature" : [
      {"id":15109262,"title":"Pharmacogenetics in cardiovascular diseases: State of the art and implementation-recommendations of the French National Network of Pharmacogenetics (RNPGx).","_sameAs":"https://www.ncbi.nlm.nih.gov/pubmed/28237404","crossReferences":[{"id":1451127922,"resource":"PubMed","resourceId":"28237404","_url":"https://www.ncbi.nlm.nih.gov/pubmed/28237404"},{"id":1451127923,"resource":"DOI","resourceId":"10.1016/j.therap.2016.09.017","_url":"http://dx.doi.org/10.1016%2Fj.therap.2016.09.017"}],"objCls":"Literature","pubDate":"2017-04-01T00:00:00-07:00","terms":[],"type":"Literature"}
    ],
    "otherPrescribingGuidance" : false,
    "pediatric" : false,
    "recommendation" : true,
    "relatedAlleles" : [
      {
        "objCls" : "Variant",
        "id" : "PA166154579",
