  "citations" : [
    {
      "id" : 15109382,
      "title" : "Pharmacogenetics of antidepressant drugs: State of the art and clinical implementation - recommendations from the French National Network of Pharmacogenetics.",
      "_sameAs" : "https://www.ncbi.nlm.nih.gov/pubmed/28237405",
      "authors" : [
        "Quaranta Sylvie",
        "Dupouey Julien",
        "Colle Romain",
        "Verstuyft CÃ©line"
      ],
      "crossReferences" : [
        {
          "id" : 1451128883,
          "resource" : "PubMed",
