    "literature" : [
      {"id":15109382,"title":"Pharmacogenetics of antidepressant drugs: State of the art and clinical implementation - recommendations from the French National Network of Pharmacogenetics.","_sameAs":"https://www.ncbi.nlm.nih.gov/pubmed/28237405","crossReferences":[{"id":1451128883,"resource":"PubMed","resourceId":"28237405","_url":"https://www.ncbi.nlm.nih.gov/pubmed/28237405"},{"id":1451128884,"resource":"DOI","resourceId":"10.1016/j.therap.2016.09.018","_url":"http://dx.doi.org/10.1016%2Fj.therap.2016.09.018"}],"objCls":"Literature","pubDate":"2017-04-01T00:00:00-07:00","terms":[],"type":"Literature"}
    ],
    "otherPrescribingGuidance" : false,
