    "literature" : [
      {"id":15105062,"title":"Clinical Pharmacogenetics Implementation Consortium Guideline (CPIC) for CYP2C9 and Nonsteroidal Anti-Inflammatory Drugs.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC8080882","crossReferences":[{"id":1451837598,"resource":"PubMed Central","resourceId":"PMC8080882","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC8080882"},{"id":1451090662,"resource":"PubMed","resourceId":"32189324","_url":"https://www.ncbi.nlm.nih.gov/pubmed/32189324"},{"id":1451090663,"resource":"DOI","resourceId":"10.1002/cpt.1830","_url":"http://dx.doi.org/10.1002%2Fcpt.1830"}],"objCls":"Literature","pubDate":"2020-08-01T00:00:00-07:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"}
    ],
    "otherPrescribingGuidance" : false,
    "pediatric" : false,
    "recommendation" : false,
    "relatedAlleles" : [],
    "relatedChemicals" : [
      {
        "objCls" : "Chemical",
