    "relatedGenes" : [
      {
        "objCls" : "Gene",
        "id" : "PA390",
        "symbol" : "ABCG2",
        "name" : "ATP binding cassette subfamily G member 2 (JR blood group)",
        "version" : 3597
      },
      {
        "objCls" : "Gene",
