    "name" : "Annotation of DPWG Guideline for phenytoin and HLA-B",
    "alternateDrugAvailable" : true,
    "cancerGenome" : false,
    "crossReferences" : [],
    "dosingInformation" : false,
    "hasTestingInfo" : true,
    "history" : [
      {
        "id" : 1451695782,
        "date" : "2022-02-25T00:00:00-08:00",
        "type" : "Create",
        "version" : 1
      },
      {
        "id" : 1451704256,
        "date" : "2022-03-03T16:33:35.593-08:00",
        "description" : "Annotation current with May 2021 DPWG Guideline release",
        "type" : "Note",
        "version" : 0
      },
      {
        "id" : 1451706360,
        "date" : "2022-03-07T16:57:41.122-08:00",
        "description" : "Added information about preemptive genotyping",
        "type" : "Update",
        "version" : 0
      },
      {
        "id" : 1451732896,
        "date" : "2022-03-28T09:57:49.538-07:00",
        "description" : "Annotation current with February 2022 DPWG guideline release",
        "type" : "Note",
        "version" : 0
      },
