      {"id":15139382,"title":"Dutch pharmacogenetics working group (DPWG) guideline for the gene-drug interaction of CYP2D6 and COMT with atomoxetine and methylphenidate.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10689464","crossReferences":[{"id":1452323500,"resource":"PubMed Central","resourceId":"PMC10689464","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10689464"},{"id":1451967460,"resource":"PubMed","resourceId":"36509836","_url":"https://www.ncbi.nlm.nih.gov/pubmed/36509836"},{"id":1451967461,"resource":"DOI","resourceId":"10.1038/s41431-022-01262-z","_url":"http://dx.doi.org/10.1038%2Fs41431-022-01262-z"}],"objCls":"Literature","pubDate":"2023-12-01T00:00:00-08:00","terms":[{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"}
