    "literature" : [
      {"id":15136122,"title":"Dutch pharmacogenetics working group guideline for the gene-drug interaction of ABCG2, HLA-B and Allopurinol, and MTHFR, folic acid and methotrexate.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10853275","crossReferences":[{"id":1452379680,"resource":"PubMed Central","resourceId":"PMC10853275","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10853275"},{"id":1451889545,"resource":"PubMed","resourceId":"36056234","_url":"https://www.ncbi.nlm.nih.gov/pubmed/36056234"},{"id":1451889546,"resource":"DOI","resourceId":"10.1038/s41431-022-01180-0","_url":"http://dx.doi.org/10.1038%2Fs41431-022-01180-0"}],"objCls":"Literature","pubDate":"2024-02-01T00:00:00-08:00","terms":[],"type":"Literature"}
