      {"id":15128762,"title":"The Clinical Pharmacogenetics Implementation Consortium Guideline for SLCO1B1, ABCG2, and CYP2C9 genotypes and Statin-Associated Musculoskeletal Symptoms.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9035072","crossReferences":[{"id":1451837607,"resource":"PubMed Central","resourceId":"PMC9035072","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9035072"},{"id":1451681580,"resource":"PubMed","resourceId":"35152405","_url":"https://www.ncbi.nlm.nih.gov/pubmed/35152405"},{"id":1451681581,"resource":"DOI","resourceId":"10.1002/cpt.2557","_url":"http://dx.doi.org/10.1002%2Fcpt.2557"}],"objCls":"Literature","pubDate":"2022-05-01T00:00:00-07:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"}
