      {"id":15135762,"title":"Expanded Clinical Pharmacogenetics Implementation Consortium Guideline for Medication Use in the Context of G6PD Genotype.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10281211","crossReferences":[{"id":1452680347,"resource":"PubMed Central","resourceId":"PMC10281211","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10281211"},{"id":1451882620,"resource":"PubMed","resourceId":"36049896","_url":"https://www.ncbi.nlm.nih.gov/pubmed/36049896"},{"id":1451882621,"resource":"DOI","resourceId":"10.1002/cpt.2735","_url":"http://dx.doi.org/10.1002%2Fcpt.2735"}],"objCls":"Literature","pubDate":"2023-05-01T00:00:00-07:00","terms":[{"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"}
