    "name" : "Annotation of CPIC Guideline for vortioxetine and CYP2D6",
    "alternateDrugAvailable" : true,
    "cancerGenome" : false,
    "crossReferences" : [],
    "descriptiveVideoId" : "gqSb7LarS24",
    "dosingInformation" : true,
    "hasTestingInfo" : false,
    "history" : [
      {
        "id" : 1452065040,
        "date" : "2023-04-10T14:25:44.488-07:00",
