      {"id":15147132,"title":"Pharmacogenetic Practice of Anticancer Drugs: Multiple Approaches for an Accurate and Comprehensive Genotyping.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10390719","crossReferences":[{"id":1452200138,"resource":"PubMed Central","resourceId":"PMC10390719","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10390719"},{"id":1452200137,"resource":"PubMed","resourceId":"37534027","_url":"https://www.ncbi.nlm.nih.gov/pubmed/37534027"},{"id":1452200139,"resource":"DOI","resourceId":"10.2147/PGPM.S412430","_url":"http://dx.doi.org/10.2147%2FPGPM.S412430"}],"objCls":"Literature","pubDate":"2022-12-01T00:00:00-08:00","terms":[{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"},{"id":1451577486,"resource":"PGx Paper Types","term":"Methods","termId":"pgxPaperTypes:1451577486"},{"id":1452054440,"resource":"PGx Paper Types","term":"Uses PharmGKB","termId":"pgxPaperTypes:1452054440"}],"type":"Literature"},
      {"id":15147302,"title":"Pharmacogenetic guidelines of The ITALIAN ASSOCIATION of Medical Oncology ASSOCIAZIONE ITALIANA di Oncologia Medica, AIOM","_sameAs":"https://www.aiom.it/wp-content/uploads/2019/10/2019_Racc-analisi-farmacogenetiche_v26.3.2020.pdf","crossReferences":[{"id":1452202360,"resource":"URL","resourceId":"https://www.aiom.it/wp-content/uploads/2019/10/2019_Racc-analisi-farmacogenetiche_v26.3.2020.pdf","_url":"https://www.aiom.it/wp-content/uploads/2019/10/2019_Racc-analisi-farmacogenetiche_v26.3.2020.pdf"}],"objCls":"Literature","pubDate":"2020-01-01T00:00:00-08:00","terms":[{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"},{"id":1452054440,"resource":"PGx Paper Types","term":"Uses PharmGKB","termId":"pgxPaperTypes:1452054440"}],"type":"Literature"}
    ],
