      {"id":15159764,"title":"CYP2C19 Genetic Testing for Oral P2Y12 Inhibitor Therapy: A Scientific Statement From the American Heart Association.","_sameAs":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC11300169","crossReferences":[{"id":1452681344,"resource":"PubMed Central","resourceId":"PMC11300169","_url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC11300169"},{"id":1452506126,"resource":"PubMed","resourceId":"38899464","_url":"https://www.ncbi.nlm.nih.gov/pubmed/38899464"},{"id":1452506127,"resource":"DOI","resourceId":"10.1161/CIR.0000000000001257","_url":"http://dx.doi.org/10.1161%2FCIR.0000000000001257"}],"objCls":"Literature","pubDate":"2024-08-01T00:00:00-07:00","terms":[{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"},{"id":1451577482,"resource":"PGx Paper Types","term":"Review","termId":"pgxPaperTypes:1451577482"},{"id":1451577485,"resource":"PGx Paper Types","term":"Pharmacoeconomics","termId":"pgxPaperTypes:1451577485"}],"type":"Literature"}
    ],
