    "literature" : [
      {"id":15236624,"title":"Guidelines From the French-Speaking Society for Histocompatibility and Immunogenetics (SFHI) for Harmonisation of HLA Genotyping in Autoimmune Diseases, Drug Hypersensitivity and Pharmacogenetics.","_sameAs":"https://www.ncbi.nlm.nih.gov/pubmed/41137743","crossReferences":[{"id":1454392032,"resource":"PubMed","resourceId":"41137743","_url":"https://www.ncbi.nlm.nih.gov/pubmed/41137743"},{"id":1454392033,"resource":"DOI","resourceId":"10.1111/tan.70442","_url":"http://dx.doi.org/10.1111%2Ftan.70442"}],"objCls":"Literature","pubDate":"2025-10-01T00:00:00-07:00","terms":[{"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}],"type":"Literature"}
    ],
    "otherPrescribingGuidance" : true,
