  "citations" : [
    {
      "id" : 15333034,
      "title" : "Clinical Pharmacogenetics Implementation Consortium (CPIC) Guideline for CYP2D6 Genotype and Use of 5-HT 3 Receptor Antagonists: 2026 Update.",
      "_sameAs" : "https://www.ncbi.nlm.nih.gov/pubmed/41979467",
      "authors" : [
        "Moore Claire",
        "Bourque Melissa S",
        "Halman Andreas",
        "AgÃºndez JosÃ© A G",
        "Prows Cynthia A",
        "Hikino Keiko",
        "Schwab Matthias",
        "Oxencis Carolyn J",
        "Chauhan Dharmisha",
        "Diekstra Meta H M",
        "Long Susie E",
        "Bell Gillian C",
        "Gaedigk Andrea",
        "Whirl-Carrillo Michelle",
        "Klein Teri E",
        "Caudle Kelly E",
        "Conyers Rachel"
      ],
      "crossReferences" : [
        {
          "id" : 1454744539,
          "resource" : "PubMed",
          "resourceId" : "41979467",
          "_url" : "https://www.ncbi.nlm.nih.gov/pubmed/41979467",
          "version" : 0
        },
        {
          "id" : 1454744540,
          "resource" : "DOI",
          "resourceId" : "10.1002/cpt.70291",
          "_url" : "http://dx.doi.org/10.1002%2Fcpt.70291",
          "version" : 0
        }
      ],
      "day" : -1,
      "hasKeyword" : true,
      "journal" : "Clinical pharmacology and therapeutics",
      "meshTerms" : [],
      "month" : 4,
      "nonHuman" : false,
      "objCls" : "Literature",
      "pediatric" : false,
      "pgkbPublication" : false,
      "pubDate" : "2026-04-01T00:00:00-07:00",
      "pubmedMeshTerms" : [],
      "summary" : "5-hydroxytryptamine type 3 (5-HT 3) receptor antagonists are used to treat nausea and vomiting and in the prevention of chemotherapy-induced, radiation-induced, and postoperative nausea and vomiting. Most of the 5-HT 3 receptor antagonists (i.e., ondansetron, tropisetron, dolasetron, palonosetron, and ramosetron) are metabolized by CYP2D6, but the extent of CYP2D6 involvement varies. CYP2D6 genetic variation can influence the metabolism of these medications, particularly ondansetron and tropisetron, thereby affecting drug efficacy. This guideline is an update to the 2016 Clinical Pharmacogenetics Implementation Consortium (CPIC) guideline for CYP2D6 genotype and use of ondansetron and tropisetron and includes updated information on CYP2D6 genetic testing and evidence tables. We summarize evidence from the published literature supporting these associations and provide therapeutic recommendations for 5-HT 3 receptor antagonists based on CYP2D6 genotype, particularly where genetic variation is associated with reduced drug efficacy (updates at https://www.clinpgx.org/guideline/PA166251457).",
      "terms" : [
        {"id":1454108620,"resource":"ClinPGx Tags","term":"CPIC","termId":"pgkbTags:1454108620"},
        {"id":1451577480,"resource":"PGx Paper Types","term":"Implementation","termId":"pgxPaperTypes:1451577480"}
      ],
      "type" : "Literature",
      "version" : 4,
      "year" : 2026
    }
  ],
  "guideline" : {
    "objCls" : "Guideline Annotation",
    "id" : "PA166436281",
    "name" : "Annotation of CPIC Guideline for dolasetron, palonosetron, ramosetron and CYP2D6",
    "alternateDrugAvailable" : false,
    "cancerGenome" : false,
    "crossReferences" : [],
    "dosingInformation" : false,
    "hasTestingInfo" : false,
    "history" : [
      {
